10|int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
11|  struct __attribute__((packed)) {
12|    int options;
13|    int width;
14|  } fuzz_config;
15|
16|  if (size >= sizeof(fuzz_config)) {
17|    /* The beginning of `data` is treated as fuzzer configuration */
18|    memcpy(&fuzz_config, data, sizeof(fuzz_config));
19|    int options = fuzz_config.options;
20|
21|    /* Mask off valid option bits */
22|    options &= (CMARK_OPT_SOURCEPOS | CMARK_OPT_HARDBREAKS | CMARK_OPT_UNSAFE | CMARK_OPT_NOBREAKS | CMARK_OPT_NORMALIZE | CMARK_OPT_VALIDATE_UTF8 | CMARK_OPT_SMART);
23|
24|    /* Remainder of input is the markdown */
25|    const char *markdown = (const char *)(data + sizeof(fuzz_config));
26|    size_t markdown_size = size - sizeof(fuzz_config);
27|    cmark_node *doc = NULL;
28|
29|    /* Use upper bits of options to select parsing mode */
30|    switch (((unsigned) fuzz_config.options >> 30) & 3) {
31|      case 0:
32|        doc = cmark_parse_document(markdown, markdown_size, options);
33|        break;
34|
35|      case 1:
36|        if (markdown_size > 0) {
37|          FILE *file = fmemopen((void *) markdown, markdown_size, "r");
38|          doc = cmark_parse_file(file, options);
39|          fclose(file);
40|        }
41|        break;
42|
43|      case 2: {
44|        size_t block_max = 20;
45|        cmark_parser *parser = cmark_parser_new(options);
46|
47|        while (markdown_size > 0) {
48|          size_t block_size = markdown_size > block_max ? block_max : markdown_size;
49|          cmark_parser_feed(parser, markdown, block_size);
50|          markdown += block_size;
51|          markdown_size -= block_size;
52|        }
53|
54|        doc = cmark_parser_finish(parser);
55|        cmark_parser_free(parser);
56|        break;
57|      }
58|
59|      case 3:
60|        free(cmark_markdown_to_html(markdown, markdown_size, options));
61|        break;
62|    }
63|
64|    if (doc != NULL) {
65|      free(cmark_render_commonmark(doc, options, fuzz_config.width));
66|      free(cmark_render_html(doc, options));
67|      free(cmark_render_latex(doc, options, fuzz_config.width));
68|      free(cmark_render_man(doc, options, fuzz_config.width));
69|      free(cmark_render_xml(doc, options));
70|
71|      cmark_node_free(doc);
72|    }
73|  }
74|  return 0;
75|}

975|static void open_new_blocks(cmark_parser *parser, cmark_node **container,
976|                            cmark_chunk *input, bool all_matched) {
977|  bool indented;
978|  cmark_list *data = NULL;
979|  bool maybe_lazy = S_type(parser->current) == CMARK_NODE_PARAGRAPH;
980|  cmark_node_type cont_type = S_type(*container);
981|  bufsize_t matched = 0;
982|  int lev = 0;
983|  bool save_partially_consumed_tab;
984|  bool has_content;
985|  int save_offset;
986|  int save_column;
987|
988|  while (cont_type != CMARK_NODE_CODE_BLOCK &&
989|         cont_type != CMARK_NODE_HTML_BLOCK) {
990|
991|    S_find_first_nonspace(parser, input);
992|    indented = parser->indent >= CODE_INDENT;
993|
994|    if (!indented && peek_at(input, parser->first_nonspace) == '>') {
995|
996|      bufsize_t blockquote_startpos = parser->first_nonspace;
997|
998|      S_advance_offset(parser, input,
999|                       parser->first_nonspace + 1 - parser->offset, false);
1000|      // optional following character
1001|      if (S_is_space_or_tab(peek_at(input, parser->offset))) {
1002|        S_advance_offset(parser, input, 1, true);
1003|      }
1004|      *container = add_child(parser, *container, CMARK_NODE_BLOCK_QUOTE,
1005|                             blockquote_startpos + 1);
1006|
1007|    } else if (!indented && (matched = scan_atx_heading_start(
1008|                                 input, parser->first_nonspace))) {
1009|      bufsize_t hashpos;
1010|      int level = 0;
1011|      bufsize_t heading_startpos = parser->first_nonspace;
1012|
1013|      S_advance_offset(parser, input,
1014|                       parser->first_nonspace + matched - parser->offset,
1015|                       false);
1016|      *container = add_child(parser, *container, CMARK_NODE_HEADING,
1017|                             heading_startpos + 1);
1018|
1019|      hashpos = cmark_chunk_strchr(input, '#', parser->first_nonspace);
1020|
1021|      while (peek_at(input, hashpos) == '#') {
1022|        level++;
1023|        hashpos++;
1024|      }
1025|
1026|      (*container)->as.heading.level = level;
1027|      (*container)->as.heading.setext = false;
1028|      (*container)->as.heading.internal_offset = matched;
1029|
1030|    } else if (!indented && (matched = scan_open_code_fence(
1031|                                 input, parser->first_nonspace))) {
1032|      *container = add_child(parser, *container, CMARK_NODE_CODE_BLOCK,
1033|                             parser->first_nonspace + 1);
1034|      (*container)->as.code.fenced = true;
1035|      (*container)->as.code.fence_char = peek_at(input, parser->first_nonspace);
1036|      (*container)->as.code.fence_length = (matched > 255) ? 255 : matched;
1037|      (*container)->as.code.fence_offset =
1038|          (int8_t)(parser->first_nonspace - parser->offset);
1039|      (*container)->as.code.info = NULL;
1040|      S_advance_offset(parser, input,
1041|                       parser->first_nonspace + matched - parser->offset,
1042|                       false);
1043|
1044|    } else if (!indented && ((matched = scan_html_block_start(
1045|                                  input, parser->first_nonspace)) ||
1046|                             (cont_type != CMARK_NODE_PARAGRAPH &&
1047|                              !maybe_lazy &&
1048|                              (matched = scan_html_block_start_7(
1049|                                   input, parser->first_nonspace))))) {
1050|      *container = add_child(parser, *container, CMARK_NODE_HTML_BLOCK,
1051|                             parser->first_nonspace + 1);
1052|      (*container)->as.html_block_type = matched;
1053|      // note, we don't adjust parser->offset because the tag is part of the
1054|      // text
1055|    } else if (!indented && cont_type == CMARK_NODE_PARAGRAPH &&
1056|               (lev =
1057|                    scan_setext_heading_line(input, parser->first_nonspace))) {
1058|      // finalize paragraph, resolving reference links
1059|      has_content = resolve_reference_link_definitions(parser);
1060|
1061|      if (has_content) {
1062|
1063|        (*container)->type = (uint16_t)CMARK_NODE_HEADING;
1064|        (*container)->as.heading.level = lev;
1065|        (*container)->as.heading.setext = true;
1066|        S_advance_offset(parser, input, input->len - 1 - parser->offset, false);
1067|      }
1068|    } else if (!indented &&
1069|               !(cont_type == CMARK_NODE_PARAGRAPH && !all_matched) &&
1070|               (parser->thematic_break_kill_pos <= parser->first_nonspace) &&
1071|               S_scan_thematic_break(parser, input, parser->first_nonspace)) {
1072|      // it's only now that we know the line is not part of a setext heading:
1073|      *container = add_child(parser, *container, CMARK_NODE_THEMATIC_BREAK,
1074|                             parser->first_nonspace + 1);
1075|      S_advance_offset(parser, input, input->len - 1 - parser->offset, false);
1076|    } else if ((!indented || cont_type == CMARK_NODE_LIST) &&
1077|               parser->indent < 4 &&
1078|               (matched = parse_list_marker(
1079|                    parser->mem, input, parser->first_nonspace,
1080|                    (*container)->type == CMARK_NODE_PARAGRAPH, &data))) {
1081|
1082|      // Note that we can have new list items starting with >= 4
1083|      // spaces indent, as long as the list container is still open.
1084|      int i = 0;
1085|
1086|      // compute padding:
1087|      S_advance_offset(parser, input,
1088|                       parser->first_nonspace + matched - parser->offset,
1089|                       false);
1090|
1091|      save_partially_consumed_tab = parser->partially_consumed_tab;
1092|      save_offset = parser->offset;
1093|      save_column = parser->column;
1094|
1095|      while (parser->column - save_column <= 5 &&
1096|             S_is_space_or_tab(peek_at(input, parser->offset))) {
1097|        S_advance_offset(parser, input, 1, true);
1098|      }
1099|
1100|      i = parser->column - save_column;
1101|      if (i >= 5 || i < 1 ||
1102|          // only spaces after list marker:
1103|          S_is_line_end_char(peek_at(input, parser->offset))) {
1104|        data->padding = matched + 1;
1105|        parser->offset = save_offset;
1106|        parser->column = save_column;
1107|        parser->partially_consumed_tab = save_partially_consumed_tab;
1108|        if (i > 0) {
1109|          S_advance_offset(parser, input, 1, true);
1110|        }
1111|      } else {
1112|        data->padding = matched + i;
1113|      }
1114|
1115|      // check container; if it's a list, see if this list item
1116|      // can continue the list; otherwise, create a list container.
1117|
1118|      data->marker_offset = parser->indent;
1119|
1120|      if (cont_type != CMARK_NODE_LIST ||
1121|          !lists_match(&((*container)->as.list), data)) {
1122|        *container = add_child(parser, *container, CMARK_NODE_LIST,
1123|                               parser->first_nonspace + 1);
1124|
1125|        memcpy(&((*container)->as.list), data, sizeof(*data));
1126|      }
1127|
1128|      // add the list item
1129|      *container = add_child(parser, *container, CMARK_NODE_ITEM,
1130|                             parser->first_nonspace + 1);
1131|      /* TODO: static */
1132|      memcpy(&((*container)->as.list), data, sizeof(*data));
1133|      parser->mem->free(data);
1134|    } else if (indented && !maybe_lazy && !parser->blank) {
1135|      S_advance_offset(parser, input, CODE_INDENT, true);
1136|      *container = add_child(parser, *container, CMARK_NODE_CODE_BLOCK,
1137|                             parser->offset + 1);
1138|      (*container)->as.code.fenced = false;
1139|      (*container)->as.code.fence_char = 0;
1140|      (*container)->as.code.fence_length = 0;
1141|      (*container)->as.code.fence_offset = 0;
1142|      (*container)->as.code.info = NULL;
1143|
1144|    } else {
1145|      break;
1146|    }
1147|
1148|    if (accepts_lines(S_type(*container))) {
1149|      // if it's a line container, it can't contain other containers
1150|      break;
1151|    }
1152|
1153|    cont_type = S_type(*container);
1154|    maybe_lazy = false;
1155|  }
