851|static cmark_node *handle_entity(subject *subj) {
852|  cmark_strbuf ent = CMARK_BUF_INIT(subj->mem);
853|  bufsize_t len;
854|
855|  advance(subj);
856|
857|  len = houdini_unescape_ent(&ent, subj->input.data + subj->pos,
858|                             subj->input.len - subj->pos);
859|
860|  if (len <= 0)
861|    return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("&"));
862|
863|  subj->pos += len;
864|  return make_str_from_buf(subj, subj->pos - 1 - len, subj->pos - 1, &ent);
