867|// Clean a URL: remove surrounding whitespace, and remove \ that escape
868|// punctuation.
869|unsigned char *cmark_clean_url(cmark_mem *mem, cmark_chunk *url) {
870|  cmark_strbuf buf = CMARK_BUF_INIT(mem);
871|
872|  cmark_chunk_trim(url);
873|
