1005|// Parse a link label.  Returns 1 if successful.
1006|// Note:  unescaped brackets are not allowed in labels.
1007|// The label begins with `[` and ends with the first `]` character
1008|// encountered.  Backticks in labels do not start code spans.
1009|static int link_label(subject *subj, cmark_chunk *raw_label) {
1010|  bufsize_t startpos = subj->pos;
1011|  int length = 0;
1012|  unsigned char c;
1013|
1014|  // advance past [
1015|  if (peek_char(subj) == '[') {
1016|    advance(subj);
1017|  } else {
1018|    return 0;
1019|  }
1020|
1021|  while ((c = peek_char(subj)) && c != '[' && c != ']') {
1022|    if (c == '\\') {
1023|      advance(subj);
1024|      length++;
1025|      if (cmark_ispunct(peek_char(subj))) {
1026|        advance(subj);
1027|        length++;
1028|      }
1029|    } else {
1030|      advance(subj);
1031|      length++;
1032|    }
1033|    if (length > MAX_LINK_LABEL_LENGTH) {
1034|      goto noMatch;
1035|    }
1036|  }
1037|
1038|  if (c == ']') { // match found
1039|    *raw_label =
1040|        cmark_chunk_dup(&subj->input, startpos + 1, subj->pos - (startpos + 1));
1041|    cmark_chunk_trim(raw_label);
1042|    advance(subj); // advance past ]
1043|    return 1;
1044|  }
1045|
1046|noMatch:
1047|  subj->pos = startpos; // rewind
1048|  return 0;
