1416|  while (!is_eof(&subj) && parse_inline(&subj, parent, options))
1417|    ;
1418|
1419|  process_emphasis(&subj, 0);
1420|  // free bracket and delim stack
1421|  while (subj.last_delim) {
1422|    remove_delimiter(&subj, subj.last_delim);
1423|  }
1424|  while (subj.last_bracket) {
