834|// Parse backslash-escape or just a backslash, returning an inline.
835|static cmark_node *handle_backslash(subject *subj) {
836|  advance(subj);
837|  unsigned char nextchar = peek_char(subj);
838|  if (cmark_ispunct(
839|          nextchar)) { // only ascii symbols and newline can be escaped
840|    advance(subj);
841|    return make_str(subj, subj->pos - 2, subj->pos - 1, cmark_chunk_dup(&subj->input, subj->pos - 1, 1));
842|  } else if (!is_eof(subj) && skip_line_end(subj)) {
843|    return make_linebreak(subj->mem);
844|  } else {
845|    return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("\\"));
846|  }
