903|// Parse an autolink or HTML tag.
904|// Assumes the subject has a '<' character at the current position.
905|static cmark_node *handle_pointy_brace(subject *subj, int options) {
906|  bufsize_t matchlen = 0;
907|  cmark_chunk contents;
908|
909|  advance(subj); // advance past first <
910|
911|  // first try to match a URL autolink
912|  matchlen = scan_autolink_uri(&subj->input, subj->pos);
913|  if (matchlen > 0) {
914|    contents = cmark_chunk_dup(&subj->input, subj->pos, matchlen - 1);
915|    subj->pos += matchlen;
916|
917|    return make_autolink(subj, subj->pos - 1 - matchlen, subj->pos - 1, contents, 0);
918|  }
919|
920|  // next try to match an email autolink
921|  matchlen = scan_autolink_email(&subj->input, subj->pos);
922|  if (matchlen > 0) {
923|    contents = cmark_chunk_dup(&subj->input, subj->pos, matchlen - 1);
924|    subj->pos += matchlen;
925|
926|    return make_autolink(subj, subj->pos - 1 - matchlen, subj->pos - 1, contents, 1);
927|  }
928|
929|  // finally, try to match an html tag
930|  if (subj->pos + 2 <= subj->input.len) {
931|    int c = subj->input.data[subj->pos];
932|    if (c == '!' && (subj->flags & FLAG_SKIP_HTML_COMMENT) == 0) {
933|      c = subj->input.data[subj->pos+1];
934|      if (c == '-' && subj->input.data[subj->pos+2] == '-') {
935|	if (subj->input.data[subj->pos+3] == '>') {
936|	  matchlen = 4;
937|	} else if (subj->input.data[subj->pos+3] == '-' &&
938|                   subj->input.data[subj->pos+4] == '>') {
939|          matchlen = 5;
940|        } else {
941|          matchlen = scan_html_comment(&subj->input, subj->pos + 1);
942|          if (matchlen > 0) {
943|            matchlen += 1; // prefix "<"
944|	  } else { // no match through end of input: set a flag so
945|		   // we don't reparse looking for -->:
946|	    subj->flags |= FLAG_SKIP_HTML_COMMENT;
947|	  }
948|	}
949|      } else if (c == '[') {
950|        if ((subj->flags & FLAG_SKIP_HTML_CDATA) == 0) {
951|          matchlen = scan_html_cdata(&subj->input, subj->pos + 2);
952|          if (matchlen > 0) {
953|            // The regex doesn't require the final "]]>". But if we're not at
954|            // the end of input, it must come after the match. Otherwise,
955|            // disable subsequent scans to avoid quadratic behavior.
956|            matchlen += 5; // prefix "![", suffix "]]>"
957|            if (subj->pos + matchlen > subj->input.len) {
958|              subj->flags |= FLAG_SKIP_HTML_CDATA;
959|              matchlen = 0;
960|            }
961|          }
962|        }
963|      } else if ((subj->flags & FLAG_SKIP_HTML_DECLARATION) == 0) {
964|        matchlen = scan_html_declaration(&subj->input, subj->pos + 1);
965|        if (matchlen > 0) {
966|          matchlen += 2; // prefix "!", suffix ">"
967|          if (subj->pos + matchlen > subj->input.len) {
968|            subj->flags |= FLAG_SKIP_HTML_DECLARATION;
969|            matchlen = 0;
970|          }
971|        }
972|      }
973|    } else if (c == '?') {
974|      if ((subj->flags & FLAG_SKIP_HTML_PI) == 0) {
975|        // Note that we allow an empty match.
976|        matchlen = scan_html_pi(&subj->input, subj->pos + 1);
977|        matchlen += 3; // prefix "?", suffix "?>"
978|        if (subj->pos + matchlen > subj->input.len) {
979|          subj->flags |= FLAG_SKIP_HTML_PI;
980|          matchlen = 0;
981|        }
982|      }
983|    } else {
984|      matchlen = scan_html_tag(&subj->input, subj->pos);
985|    }
986|  }
987|  if (matchlen > 0) {
988|    const unsigned char *src = subj->input.data + subj->pos - 1;
989|    bufsize_t len = matchlen + 1;
990|    subj->pos += matchlen;
991|    cmark_node *node = make_literal(subj, CMARK_NODE_HTML_INLINE,
992|                                    subj->pos - matchlen - 1, subj->pos - 1);
993|    node->data = (unsigned char *)subj->mem->realloc(NULL, len + 1);
994|    memcpy(node->data, src, len);
995|    node->data[len] = 0;
996|    node->len = len;
997|    adjust_subj_node_newlines(subj, node, matchlen, 1, options);
998|    return node;
999|  }
1000|
1001|  // if nothing matches, just return the opening <:
1002|  return make_str(subj, subj->pos - 1, subj->pos - 1, cmark_chunk_literal("<"));
1003|}
1004|
1005|// Parse a link label.  Returns 1 if successful.
1006|// Note:  unescaped brackets are not allowed in labels.
1007|// The label begins with `[` and ends with the first `]` character
1008|// encountered.  Backticks in labels do not start code spans.
1009|static int link_label(subject *subj, cmark_chunk *raw_label) {
1010|  bufsize_t startpos = subj->pos;
1011|  int length = 0;
1012|  unsigned char c;
1013|
1014|  // advance past [
1015|  if (peek_char(subj) == '[') {
1016|    advance(subj);
1017|  } else {
1018|    return 0;
1019|  }
1020|
1021|  while ((c = peek_char(subj)) && c != '[' && c != ']') {
1022|    if (c == '\\') {
1023|      advance(subj);
1024|      length++;
