1228|
1229|match:
1230|  inl = make_simple(subj->mem, is_image ? CMARK_NODE_IMAGE : CMARK_NODE_LINK);
1231|  inl->as.link.url = url;
1232|  inl->as.link.title = title;
1233|  inl->start_line = inl->end_line = subj->line;
1234|  inl->start_column = opener->inl_text->start_column;
1235|  inl->end_column = subj->pos + subj->column_offset + subj->block_offset;
