1406|// Parse inlines from parent's string_content, adding as children of parent.
1407|void cmark_parse_inlines(cmark_mem *mem, cmark_node *parent,
1408|                         cmark_reference_map *refmap, int options) {
1409|  int internal_offset = parent->type == CMARK_NODE_HEADING ?
1410|    parent->as.heading.internal_offset : 0;
1411|  subject subj;
1412|  cmark_chunk content = {parent->data, parent->len};
1413|  subject_from_buf(mem, parent->start_line, parent->start_column - 1 + internal_offset, &subj, &content, refmap);
1414|  cmark_chunk_rtrim(&subj.input);
1415|
1416|  while (!is_eof(&subj) && parse_inline(&subj, parent, options))
1417|    ;
1418|
1419|  process_emphasis(&subj, 0);
1420|  // free bracket and delim stack
1421|  while (subj.last_delim) {
1422|    remove_delimiter(&subj, subj.last_delim);
1423|  }
1424|  while (subj.last_bracket) {
1425|    pop_bracket(&subj);
1426|  }
