255|static cmark_node *finalize(cmark_parser *parser, cmark_node *b) {
256|  bufsize_t pos;
257|  cmark_node *item;
258|  cmark_node *subitem;
259|  cmark_node *parent;
260|  bool has_content;
261|
262|  parent = b->parent;
263|  assert(b->flags &
264|         CMARK_NODE__OPEN); // shouldn't call finalize on closed blocks
265|  b->flags &= ~CMARK_NODE__OPEN;
266|
267|  if (parser->curline.size == 0) {
268|    // end of input - line number has not been incremented
269|    b->end_line = parser->line_number;
270|    b->end_column = parser->last_line_length;
271|  } else if (S_type(b) == CMARK_NODE_DOCUMENT ||
272|             (S_type(b) == CMARK_NODE_CODE_BLOCK && b->as.code.fenced) ||
273|             (S_type(b) == CMARK_NODE_HEADING && b->as.heading.setext)) {
274|    b->end_line = parser->line_number;
275|    b->end_column = parser->curline.size;
276|    if (b->end_column && parser->curline.ptr[b->end_column - 1] == '\n')
277|      b->end_column -= 1;
278|    if (b->end_column && parser->curline.ptr[b->end_column - 1] == '\r')
279|      b->end_column -= 1;
280|  } else {
281|    b->end_line = parser->line_number - 1;
282|    b->end_column = parser->last_line_length;
283|  }
284|
285|  cmark_strbuf *node_content = &parser->content;
286|
287|  switch (S_type(b)) {
288|  case CMARK_NODE_PARAGRAPH:
289|  {
290|    has_content = resolve_reference_link_definitions(parser);
291|    if (!has_content) {
292|      // remove blank node (former reference def)
293|      cmark_node_free(b);
294|    } else {
295|      b->len = node_content->size;
296|      b->data = cmark_strbuf_detach(node_content);
297|    }
298|    break;
299|  }
300|
301|  case CMARK_NODE_CODE_BLOCK:
302|    if (!b->as.code.fenced) { // indented code
303|      remove_trailing_blank_lines(node_content);
304|      cmark_strbuf_putc(node_content, '\n');
305|    } else {
306|      // first line of contents becomes info
307|      for (pos = 0; pos < node_content->size; ++pos) {
308|        if (S_is_line_end_char(node_content->ptr[pos]))
309|          break;
310|      }
311|      assert(pos < node_content->size);
312|
313|      if (pos == 0) {
314|        b->as.code.info = NULL;
315|      } else {
316|        cmark_strbuf tmp = CMARK_BUF_INIT(parser->mem);
317|        houdini_unescape_html_f(&tmp, node_content->ptr, pos);
318|        cmark_strbuf_trim(&tmp);
319|        cmark_strbuf_unescape(&tmp);
320|        b->as.code.info = cmark_strbuf_detach(&tmp);
321|      }
322|
323|      if (node_content->ptr[pos] == '\r')
324|        pos += 1;
325|      if (node_content->ptr[pos] == '\n')
326|        pos += 1;
327|      cmark_strbuf_drop(node_content, pos);
328|    }
329|    b->len = node_content->size;
330|    b->data = cmark_strbuf_detach(node_content);
331|    break;
332|
333|  case CMARK_NODE_HEADING:
334|  case CMARK_NODE_HTML_BLOCK:
335|    b->len = node_content->size;
336|    b->data = cmark_strbuf_detach(node_content);
337|    break;
338|
339|  case CMARK_NODE_LIST:      // determine tight/loose status
340|    b->as.list.tight = true; // tight by default
341|    item = b->first_child;
342|
343|    while (item) {
344|      // check for non-final non-empty list item ending with blank line:
345|      if (S_last_line_blank(item) && item->next) {
346|        b->as.list.tight = false;
347|        break;
348|      }
349|      // recurse into children of list item, to see if there are
350|      // spaces between them:
351|      subitem = item->first_child;
352|      while (subitem) {
353|        if ((item->next || subitem->next) &&
354|            S_ends_with_blank_line(subitem)) {
355|          b->as.list.tight = false;
356|          break;
357|        }
358|        subitem = subitem->next;
359|      }
360|      if (!(b->as.list.tight)) {
361|        break;
362|      }
363|      item = item->next;
364|    }
365|
366|    break;
367|
368|  default:
369|    break;
370|  }
371|
372|  return parent;
373|}
