653|static void chop_trailing_hashtags(cmark_chunk *ch) {
654|  bufsize_t n, orig_n;
655|
656|  cmark_chunk_rtrim(ch);
657|  orig_n = n = ch->len - 1;
658|
659|  // if string ends in space followed by #s, remove these:
660|  while (n >= 0 && peek_at(ch, n) == '#')
661|    n--;
662|
663|  // Check for a space before the final #s:
664|  if (n != orig_n && n >= 0 && S_is_space_or_tab(peek_at(ch, n))) {
665|    ch->len = n;
666|    cmark_chunk_rtrim(ch);
667|  }
