1076|    } else if ((!indented || cont_type == CMARK_NODE_LIST) &&
1077|               parser->indent < 4 &&
1078|               (matched = parse_list_marker(
1079|                    parser->mem, input, parser->first_nonspace,
1080|                    (*container)->type == CMARK_NODE_PARAGRAPH, &data))) {
1081|
1082|      // Note that we can have new list items starting with >= 4
1083|      // spaces indent, as long as the list container is still open.
1084|      int i = 0;
1085|
1086|      // compute padding:
1087|      S_advance_offset(parser, input,
1088|                       parser->first_nonspace + matched - parser->offset,
1089|                       false);
1090|
1091|      save_partially_consumed_tab = parser->partially_consumed_tab;
1092|      save_offset = parser->offset;
1093|      save_column = parser->column;
1094|
1095|      while (parser->column - save_column <= 5 &&
1096|             S_is_space_or_tab(peek_at(input, parser->offset))) {
1097|        S_advance_offset(parser, input, 1, true);
1098|      }
1099|
1100|      i = parser->column - save_column;
1101|      if (i >= 5 || i < 1 ||
1102|          // only spaces after list marker:
1103|          S_is_line_end_char(peek_at(input, parser->offset))) {
1104|        data->padding = matched + 1;
1105|        parser->offset = save_offset;
1106|        parser->column = save_column;
1107|        parser->partially_consumed_tab = save_partially_consumed_tab;
1108|        if (i > 0) {
1109|          S_advance_offset(parser, input, 1, true);
1110|        }
1111|      } else {
1112|        data->padding = matched + i;
1113|      }
1114|
1115|      // check container; if it's a list, see if this list item
1116|      // can continue the list; otherwise, create a list container.
1117|
1118|      data->marker_offset = parser->indent;
1119|
1120|      if (cont_type != CMARK_NODE_LIST ||
1121|          !lists_match(&((*container)->as.list), data)) {
1122|        *container = add_child(parser, *container, CMARK_NODE_LIST,
1123|                               parser->first_nonspace + 1);
1124|
1125|        memcpy(&((*container)->as.list), data, sizeof(*data));
1126|      }
1127|
1128|      // add the list item
1129|      *container = add_child(parser, *container, CMARK_NODE_ITEM,
1130|                             parser->first_nonspace + 1);
1131|      /* TODO: static */
1132|      memcpy(&((*container)->as.list), data, sizeof(*data));
1133|      parser->mem->free(data);
1134|    } else if (indented && !maybe_lazy && !parser->blank) {
1135|      S_advance_offset(parser, input, CODE_INDENT, true);
1136|      *container = add_child(parser, *container, CMARK_NODE_CODE_BLOCK,
1137|                             parser->offset + 1);
1138|      (*container)->as.code.fenced = false;
1139|      (*container)->as.code.fence_char = 0;
1140|      (*container)->as.code.fence_length = 0;
1141|      (*container)->as.code.fence_offset = 0;
1142|      (*container)->as.code.info = NULL;
1143|
1144|    } else {
1145|      break;
1146|    }
1147|
1148|    if (accepts_lines(S_type(*container))) {
1149|      // if it's a line container, it can't contain other containers
1150|      break;
1151|    }
1152|
1153|    cont_type = S_type(*container);
1154|    maybe_lazy = false;
1155|  }
