224|// Check to see if a node ends with a blank line, descending
225|// if needed into lists and sublists.
226|static bool S_ends_with_blank_line(cmark_node *node) {
227|  if (S_last_line_checked(node)) {
228|    return(S_last_line_blank(node));
229|  } else if ((S_type(node) == CMARK_NODE_LIST ||
230|              S_type(node) == CMARK_NODE_ITEM) && node->last_child) {
231|    S_set_last_line_checked(node);
232|    return(S_ends_with_blank_line(node->last_child));
233|  } else {
234|    S_set_last_line_checked(node);
235|    return (S_last_line_blank(node));
236|  }
237|}
