239|// returns true if content remains after link defs are resolved.
240|static bool resolve_reference_link_definitions(cmark_parser *parser) {
241|  bufsize_t pos;
242|  cmark_strbuf *node_content = &parser->content;
243|  cmark_chunk chunk = {node_content->ptr, node_content->size};
244|  while (chunk.len && chunk.data[0] == '[' &&
245|         (pos = cmark_parse_reference_inline(parser->mem, &chunk,
246|                                             parser->refmap))) {
247|
248|    chunk.data += pos;
249|    chunk.len -= pos;
250|  }
251|  cmark_strbuf_drop(node_content, (node_content->size - chunk.len));
252|  return !is_blank(node_content, 0);
253|}
