424|// Attempts to parse a list item marker (bullet or enumerated).
425|// On success, returns length of the marker, and populates
426|// data with the details.  On failure, returns 0.
427|static bufsize_t parse_list_marker(cmark_mem *mem, cmark_chunk *input,
428|                                   bufsize_t pos, bool interrupts_paragraph,
429|                                   cmark_list **dataptr) {
430|  unsigned char c;
431|  bufsize_t startpos;
432|  cmark_list *data;
433|  bufsize_t i;
434|
435|  startpos = pos;
436|  c = peek_at(input, pos);
437|
438|  if (c == '*' || c == '-' || c == '+') {
439|    pos++;
440|    if (!cmark_isspace(peek_at(input, pos))) {
441|      return 0;
442|    }
443|
444|    if (interrupts_paragraph) {
445|      i = pos;
446|      // require non-blank content after list marker:
447|      while (S_is_space_or_tab(peek_at(input, i))) {
448|        i++;
449|      }
450|      if (peek_at(input, i) == '\n') {
451|        return 0;
452|      }
453|    }
454|
455|    data = (cmark_list *)mem->calloc(1, sizeof(*data));
456|    data->marker_offset = 0; // will be adjusted later
457|    data->list_type = CMARK_BULLET_LIST;
458|    data->bullet_char = c;
459|    data->start = 0;
460|    data->delimiter = CMARK_NO_DELIM;
461|    data->tight = false;
462|  } else if (cmark_isdigit(c)) {
463|    int start = 0;
464|    int digits = 0;
465|
466|    do {
467|      start = (10 * start) + (peek_at(input, pos) - '0');
468|      pos++;
469|      digits++;
470|      // We limit to 9 digits to avoid overflow,
471|      // assuming max int is 2^31 - 1
472|      // This also seems to be the limit for 'start' in some browsers.
473|    } while (digits < 9 && cmark_isdigit(peek_at(input, pos)));
474|
475|    if (interrupts_paragraph && start != 1) {
476|      return 0;
477|    }
478|    c = peek_at(input, pos);
479|    if (c == '.' || c == ')') {
480|      pos++;
481|      if (!cmark_isspace(peek_at(input, pos))) {
482|        return 0;
483|      }
484|      if (interrupts_paragraph) {
485|        // require non-blank content after list marker:
486|        i = pos;
487|        while (S_is_space_or_tab(peek_at(input, i))) {
488|          i++;
489|        }
490|        if (S_is_line_end_char(peek_at(input, i))) {
491|          return 0;
492|        }
493|      }
494|
495|      data = (cmark_list *)mem->calloc(1, sizeof(*data));
496|      data->marker_offset = 0; // will be adjusted later
497|      data->list_type = CMARK_ORDERED_LIST;
498|      data->bullet_char = 0;
499|      data->start = start;
500|      data->delimiter = (c == '.' ? CMARK_PERIOD_DELIM : CMARK_PAREN_DELIM);
501|      data->tight = false;
502|    } else {
503|      return 0;
504|    }
505|  } else {
506|    return 0;
507|  }
508|
509|  *dataptr = data;
510|  return (pos - startpos);
511|}
512|
513|// Return 1 if list item belongs in list, else 0.
514|static int lists_match(cmark_list *list_data, cmark_list *item_data) {
515|  return (list_data->list_type == item_data->list_type &&
516|          list_data->delimiter == item_data->delimiter &&
517|          // list_data->marker_offset == item_data.marker_offset &&
518|          list_data->bullet_char == item_data->bullet_char);
519|}
