670|// Check for thematic break.  On failure, return 0 and update
671|// thematic_break_kill_pos with the index at which the
672|// parse fails.  On success, return length of match.
673|// "...three or more hyphens, asterisks,
674|// or underscores on a line by themselves. If you wish, you may use
675|// spaces between the hyphens or asterisks."
676|static int S_scan_thematic_break(cmark_parser *parser, cmark_chunk *input,
677|                                 bufsize_t offset) {
678|  bufsize_t i;
679|  char c;
680|  char nextc = '\0';
681|  int count;
682|  i = offset;
683|  c = peek_at(input, i);
684|  if (!(c == '*' || c == '_' || c == '-')) {
685|    parser->thematic_break_kill_pos = i;
686|    return 0;
687|  }
688|  count = 1;
689|  while ((nextc = peek_at(input, ++i))) {
690|    if (nextc == c) {
691|      count++;
692|    } else if (nextc != ' ' && nextc != '\t') {
693|      break;
694|    }
695|  }
696|  if (count >= 3 && (nextc == '\r' || nextc == '\n')) {
697|    return (i - offset) + 1;
698|  } else {
699|    parser->thematic_break_kill_pos = i;
700|    return 0;
701|  }
