251|static bufsize_t cmark_set_cstr(cmark_mem *mem, unsigned char **dst,
252|                                const char *src) {
253|  unsigned char *old = *dst;
254|  bufsize_t len;
255|
256|  if (src && src[0]) {
257|      len = (bufsize_t)strlen(src);
258|      *dst = (unsigned char *)mem->realloc(NULL, len + 1);
259|      memcpy(*dst, src, len + 1);
260|  } else {
261|      len = 0;
262|      *dst = NULL;
263|  }
264|  if (old) {
265|    mem->free(old);
266|  }
267|
268|  return len;
269|}

