154|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
155|                         cmark_event_type ev_type, int options) {
156|  cmark_node *tmp;
157|  int list_number;
158|  cmark_delim_type list_delim;
159|  size_t numticks;
160|  bool extra_spaces;
161|  size_t i;
162|  bool entering = (ev_type == CMARK_EVENT_ENTER);
163|  const char *info, *code, *title;
164|  char fencechar[2] = {'\0', '\0'};
165|  size_t code_len;
166|  char listmarker[LISTMARKER_SIZE];
167|  const char *emph_delim;
168|  bool first_in_list_item;
169|  bufsize_t marker_width;
170|  bool has_nonspace;
171|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options) &&
172|                    !(CMARK_OPT_HARDBREAKS & options);
173|
174|  // Don't adjust tight list status til we've started the list.
175|  // Otherwise we lose the blank line between a paragraph and
176|  // a following list.
177|  if (entering) {
178|    if (node->parent && node->parent->type == CMARK_NODE_ITEM) {
179|      renderer->in_tight_list_item = node->parent->parent->as.list.tight;
180|    }
181|  } else {
182|    if (node->type == CMARK_NODE_LIST) {
183|      renderer->in_tight_list_item =
184|        node->parent &&
185|        node->parent->type == CMARK_NODE_ITEM &&
186|        node->parent->parent->as.list.tight;
187|    }
188|  }
189|
190|  switch (node->type) {
191|  case CMARK_NODE_DOCUMENT:
192|    break;
193|
194|  case CMARK_NODE_BLOCK_QUOTE:
195|    if (entering) {
196|      LIT("> ");
197|      renderer->begin_content = true;
198|      cmark_strbuf_puts(renderer->prefix, "> ");
199|    } else {
200|      cmark_strbuf_truncate(renderer->prefix, renderer->prefix->size - 2);
201|      BLANKLINE();
202|    }
203|    break;
204|
205|  case CMARK_NODE_LIST:
206|    if (!entering && node->next && (node->next->type == CMARK_NODE_LIST)) {
207|      // this ensures that a following indented code block or list will be
208|      // inteprereted correctly.
209|      CR();
210|      LIT("<!-- end list -->");
211|      BLANKLINE();
212|    }
213|    break;
214|
215|  case CMARK_NODE_ITEM:
216|    if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
217|      marker_width = 4;
218|    } else {
219|      list_number = cmark_node_get_list_start(node->parent);
220|      list_delim = cmark_node_get_list_delim(node->parent);
221|      tmp = node;
222|      while (tmp->prev) {
223|        tmp = tmp->prev;
224|        list_number += 1;
225|      }
226|      // we ensure a width of at least 4 so
227|      // we get nice transition from single digits
228|      // to double
229|      snprintf(listmarker, LISTMARKER_SIZE, "%d%s%s", list_number,
230|               list_delim == CMARK_PAREN_DELIM ? ")" : ".",
231|               list_number < 10 ? "  " : " ");
232|      marker_width = (bufsize_t)strlen(listmarker);
233|    }
234|    if (entering) {
235|      if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
236|        LIT("  - ");
237|        renderer->begin_content = true;
238|      } else {
239|        LIT(listmarker);
240|        renderer->begin_content = true;
241|      }
242|      for (i = marker_width; i--;) {
243|        cmark_strbuf_putc(renderer->prefix, ' ');
244|      }
245|    } else {
246|      cmark_strbuf_truncate(renderer->prefix,
247|                            renderer->prefix->size - marker_width);
248|      CR();
249|    }
250|    break;
251|
252|  case CMARK_NODE_HEADING:
253|    if (entering) {
254|      for (i = cmark_node_get_heading_level(node); i > 0; i--) {
255|        LIT("#");
256|      }
257|      LIT(" ");
258|      renderer->begin_content = true;
259|      renderer->no_linebreaks = true;
260|    } else {
261|      renderer->no_linebreaks = false;
262|      BLANKLINE();
263|    }
264|    break;
265|
266|  case CMARK_NODE_CODE_BLOCK:
267|
268|    first_in_list_item = node->prev == NULL && node->parent &&
269|                         node->parent->type == CMARK_NODE_ITEM;
270|
271|    if (!first_in_list_item) {
272|      BLANKLINE();
273|    }
274|    info = cmark_node_get_fence_info(node);
275|    fencechar[0] = strchr(info, '`') == NULL ? '`' : '~';
276|    code = cmark_node_get_literal(node);
277|
278|    numticks = longest_backtick_sequence(code) + 1;
279|    if (numticks < 3) {
280|      numticks = 3;
281|    }
282|    for (i = 0; i < numticks; i++) {
283|      LIT(fencechar);
284|    }
285|    LIT(" ");
286|    OUT(info, false, LITERAL);
287|    CR();
288|    OUT(cmark_node_get_literal(node), false, LITERAL);
289|    CR();
290|    for (i = 0; i < numticks; i++) {
291|      LIT(fencechar);
292|    }
293|
294|    BLANKLINE();
295|    break;
296|
297|  case CMARK_NODE_HTML_BLOCK:
298|    BLANKLINE();
299|    OUT(cmark_node_get_literal(node), false, LITERAL);
300|    BLANKLINE();
301|    break;
302|
303|  case CMARK_NODE_CUSTOM_BLOCK:
304|    BLANKLINE();
305|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
306|        false, LITERAL);
307|    BLANKLINE();
308|    break;
309|
310|  case CMARK_NODE_THEMATIC_BREAK:
311|    BLANKLINE();
312|    LIT("-----");
313|    BLANKLINE();
314|    break;
315|
316|  case CMARK_NODE_PARAGRAPH:
317|    if (!entering) {
318|      BLANKLINE();
319|    }
320|    break;
321|
322|  case CMARK_NODE_TEXT:
323|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
324|    break;
325|
326|  case CMARK_NODE_LINEBREAK:
327|    if (!(CMARK_OPT_HARDBREAKS & options)) {
328|      LIT("  ");
329|    }
330|    CR();
331|    break;
332|
333|  case CMARK_NODE_SOFTBREAK:
334|    if (CMARK_OPT_HARDBREAKS & options) {
335|      LIT("  ");
336|      CR();
337|    } else if (!renderer->no_linebreaks && renderer->width == 0 &&
338|               !(CMARK_OPT_HARDBREAKS & options) &&
339|               !(CMARK_OPT_NOBREAKS & options)) {
340|      CR();
341|    } else {
342|      OUT(" ", allow_wrap, LITERAL);
343|    }
344|    break;
345|
346|  case CMARK_NODE_CODE:
347|    code = cmark_node_get_literal(node);
348|    code_len = strlen(code);
349|    numticks = shortest_unused_backtick_sequence(code);
350|    has_nonspace = false;
351|    for (i=0; i < code_len; i++) {
352|      if (code[i] != ' ') {
353|        has_nonspace = true;
354|        break;
355|      }
356|    }
357|    extra_spaces = code_len == 0 ||
358|            code[0] == '`' || code[code_len - 1] == '`' ||
359|            (has_nonspace && code[0] == ' ' && code[code_len - 1] == ' ');
360|    for (i = 0; i < numticks; i++) {
361|      LIT("`");
362|    }
363|    if (extra_spaces) {
364|      LIT(" ");
365|    }
366|    OUT(cmark_node_get_literal(node), allow_wrap, LITERAL);
367|    if (extra_spaces) {
368|      LIT(" ");
369|    }
370|    for (i = 0; i < numticks; i++) {
371|      LIT("`");
372|    }
373|    break;
374|
375|  case CMARK_NODE_HTML_INLINE:
376|    OUT(cmark_node_get_literal(node), false, LITERAL);
377|    break;
378|
379|  case CMARK_NODE_CUSTOM_INLINE:
380|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
381|        false, LITERAL);
382|    break;
383|
384|  case CMARK_NODE_STRONG:
385|    if (entering) {
386|      LIT("**");
387|    } else {
388|      LIT("**");
389|    }
390|    break;
391|
392|  case CMARK_NODE_EMPH:
393|    // If we have EMPH(EMPH(x)), we need to use *_x_*
394|    // because **x** is STRONG(x):
395|    if (node->parent && node->parent->type == CMARK_NODE_EMPH &&
396|        node->next == NULL && node->prev == NULL) {
397|      emph_delim = "_";
398|    } else {
399|      emph_delim = "*";
400|    }
401|    if (entering) {
402|      LIT(emph_delim);
403|    } else {
404|      LIT(emph_delim);
405|    }
406|    break;
407|
408|  case CMARK_NODE_LINK:
409|    if (is_autolink(node)) {
410|      if (entering) {
411|        LIT("<");
412|        if (strncmp(cmark_node_get_url(node), "mailto:", 7) == 0) {
413|          LIT((const char *)cmark_node_get_url(node) + 7);
414|        } else {
415|          LIT((const char *)cmark_node_get_url(node));
416|        }
417|        LIT(">");
418|        // return signal to skip contents of node...
419|        return 0;
420|      }
421|    } else {
422|      if (entering) {
423|        LIT("[");
424|      } else {
425|        LIT("](");
426|        OUT(cmark_node_get_url(node), false, URL);
427|        title = cmark_node_get_title(node);
428|        if (strlen(title) > 0) {
429|          LIT(" \"");
430|          OUT(title, false, TITLE);
431|          LIT("\"");
432|        }
433|        LIT(")");
434|      }
435|    }
436|    break;
437|
438|  case CMARK_NODE_IMAGE:
439|    if (entering) {
440|      LIT("![");
441|    } else {
442|      LIT("](");
443|      OUT(cmark_node_get_url(node), false, URL);
444|      title = cmark_node_get_title(node);
445|      if (strlen(title) > 0) {
446|        OUT(" \"", allow_wrap, LITERAL);
447|        OUT(title, false, TITLE);
448|        LIT("\"");
449|      }
450|      LIT(")");
451|    }
452|    break;
453|
454|  default:
455|    assert(false);
456|    break;
457|  }
458|
459|  return 1;
460|}

154|static int S_render_node(cmark_renderer *renderer, cmark_node *node,
155|                         cmark_event_type ev_type, int options) {
156|  cmark_node *tmp;
157|  int list_number;
158|  cmark_delim_type list_delim;
159|  size_t numticks;
160|  bool extra_spaces;
161|  size_t i;
162|  bool entering = (ev_type == CMARK_EVENT_ENTER);
163|  const char *info, *code, *title;
164|  char fencechar[2] = {'\0', '\0'};
165|  size_t code_len;
166|  char listmarker[LISTMARKER_SIZE];
167|  const char *emph_delim;
168|  bool first_in_list_item;
169|  bufsize_t marker_width;
170|  bool has_nonspace;
171|  bool allow_wrap = renderer->width > 0 && !(CMARK_OPT_NOBREAKS & options) &&
172|                    !(CMARK_OPT_HARDBREAKS & options);
173|
174|  // Don't adjust tight list status til we've started the list.
175|  // Otherwise we lose the blank line between a paragraph and
176|  // a following list.
177|  if (entering) {
178|    if (node->parent && node->parent->type == CMARK_NODE_ITEM) {
179|      renderer->in_tight_list_item = node->parent->parent->as.list.tight;
180|    }
181|  } else {
182|    if (node->type == CMARK_NODE_LIST) {
183|      renderer->in_tight_list_item =
184|        node->parent &&
185|        node->parent->type == CMARK_NODE_ITEM &&
186|        node->parent->parent->as.list.tight;
187|    }
188|  }
189|
190|  switch (node->type) {
191|  case CMARK_NODE_DOCUMENT:
192|    break;
193|
194|  case CMARK_NODE_BLOCK_QUOTE:
195|    if (entering) {
196|      LIT("> ");
197|      renderer->begin_content = true;
198|      cmark_strbuf_puts(renderer->prefix, "> ");
199|    } else {
200|      cmark_strbuf_truncate(renderer->prefix, renderer->prefix->size - 2);
201|      BLANKLINE();
202|    }
203|    break;
204|
205|  case CMARK_NODE_LIST:
206|    if (!entering && node->next && (node->next->type == CMARK_NODE_LIST)) {
207|      // this ensures that a following indented code block or list will be
208|      // inteprereted correctly.
209|      CR();
210|      LIT("<!-- end list -->");
211|      BLANKLINE();
212|    }
213|    break;
214|
215|  case CMARK_NODE_ITEM:
216|    if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
217|      marker_width = 4;
218|    } else {
219|      list_number = cmark_node_get_list_start(node->parent);
220|      list_delim = cmark_node_get_list_delim(node->parent);
221|      tmp = node;
222|      while (tmp->prev) {
223|        tmp = tmp->prev;
224|        list_number += 1;
225|      }
226|      // we ensure a width of at least 4 so
227|      // we get nice transition from single digits
228|      // to double
229|      snprintf(listmarker, LISTMARKER_SIZE, "%d%s%s", list_number,
230|               list_delim == CMARK_PAREN_DELIM ? ")" : ".",
231|               list_number < 10 ? "  " : " ");
232|      marker_width = (bufsize_t)strlen(listmarker);
233|    }
234|    if (entering) {
235|      if (cmark_node_get_list_type(node->parent) == CMARK_BULLET_LIST) {
236|        LIT("  - ");
237|        renderer->begin_content = true;
238|      } else {
239|        LIT(listmarker);
240|        renderer->begin_content = true;
241|      }
242|      for (i = marker_width; i--;) {
243|        cmark_strbuf_putc(renderer->prefix, ' ');
244|      }
245|    } else {
246|      cmark_strbuf_truncate(renderer->prefix,
247|                            renderer->prefix->size - marker_width);
248|      CR();
249|    }
250|    break;
251|
252|  case CMARK_NODE_HEADING:
253|    if (entering) {
254|      for (i = cmark_node_get_heading_level(node); i > 0; i--) {
255|        LIT("#");
256|      }
257|      LIT(" ");
258|      renderer->begin_content = true;
259|      renderer->no_linebreaks = true;
260|    } else {
261|      renderer->no_linebreaks = false;
262|      BLANKLINE();
263|    }
264|    break;
265|
266|  case CMARK_NODE_CODE_BLOCK:
267|
268|    first_in_list_item = node->prev == NULL && node->parent &&
269|                         node->parent->type == CMARK_NODE_ITEM;
270|
271|    if (!first_in_list_item) {
272|      BLANKLINE();
273|    }
274|    info = cmark_node_get_fence_info(node);
275|    fencechar[0] = strchr(info, '`') == NULL ? '`' : '~';
276|    code = cmark_node_get_literal(node);
277|
278|    numticks = longest_backtick_sequence(code) + 1;
279|    if (numticks < 3) {
280|      numticks = 3;
281|    }
282|    for (i = 0; i < numticks; i++) {
283|      LIT(fencechar);
284|    }
285|    LIT(" ");
286|    OUT(info, false, LITERAL);
287|    CR();
288|    OUT(cmark_node_get_literal(node), false, LITERAL);
289|    CR();
290|    for (i = 0; i < numticks; i++) {
291|      LIT(fencechar);
292|    }
293|
294|    BLANKLINE();
295|    break;
296|
297|  case CMARK_NODE_HTML_BLOCK:
298|    BLANKLINE();
299|    OUT(cmark_node_get_literal(node), false, LITERAL);
300|    BLANKLINE();
301|    break;
302|
303|  case CMARK_NODE_CUSTOM_BLOCK:
304|    BLANKLINE();
305|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
306|        false, LITERAL);
307|    BLANKLINE();
308|    break;
309|
310|  case CMARK_NODE_THEMATIC_BREAK:
311|    BLANKLINE();
312|    LIT("-----");
313|    BLANKLINE();
314|    break;
315|
316|  case CMARK_NODE_PARAGRAPH:
317|    if (!entering) {
318|      BLANKLINE();
319|    }
320|    break;
321|
322|  case CMARK_NODE_TEXT:
323|    OUT(cmark_node_get_literal(node), allow_wrap, NORMAL);
324|    break;
325|
326|  case CMARK_NODE_LINEBREAK:
327|    if (!(CMARK_OPT_HARDBREAKS & options)) {
328|      LIT("  ");
329|    }
330|    CR();
331|    break;
332|
333|  case CMARK_NODE_SOFTBREAK:
334|    if (CMARK_OPT_HARDBREAKS & options) {
335|      LIT("  ");
336|      CR();
337|    } else if (!renderer->no_linebreaks && renderer->width == 0 &&
338|               !(CMARK_OPT_HARDBREAKS & options) &&
339|               !(CMARK_OPT_NOBREAKS & options)) {
340|      CR();
341|    } else {
342|      OUT(" ", allow_wrap, LITERAL);
343|    }
344|    break;
345|
346|  case CMARK_NODE_CODE:
347|    code = cmark_node_get_literal(node);
348|    code_len = strlen(code);
349|    numticks = shortest_unused_backtick_sequence(code);
350|    has_nonspace = false;
351|    for (i=0; i < code_len; i++) {
352|      if (code[i] != ' ') {
353|        has_nonspace = true;
354|        break;
355|      }
356|    }
357|    extra_spaces = code_len == 0 ||
358|            code[0] == '`' || code[code_len - 1] == '`' ||
359|            (has_nonspace && code[0] == ' ' && code[code_len - 1] == ' ');
360|    for (i = 0; i < numticks; i++) {
361|      LIT("`");
362|    }
363|    if (extra_spaces) {
364|      LIT(" ");
365|    }
366|    OUT(cmark_node_get_literal(node), allow_wrap, LITERAL);
367|    if (extra_spaces) {
368|      LIT(" ");
369|    }
370|    for (i = 0; i < numticks; i++) {
371|      LIT("`");
372|    }
373|    break;
374|
375|  case CMARK_NODE_HTML_INLINE:
376|    OUT(cmark_node_get_literal(node), false, LITERAL);
377|    break;
378|
379|  case CMARK_NODE_CUSTOM_INLINE:
380|    OUT(entering ? cmark_node_get_on_enter(node) : cmark_node_get_on_exit(node),
381|        false, LITERAL);
382|    break;
383|
384|  case CMARK_NODE_STRONG:
385|    if (entering) {
386|      LIT("**");
387|    } else {
388|      LIT("**");
389|    }
390|    break;
391|
392|  case CMARK_NODE_EMPH:
393|    // If we have EMPH(EMPH(x)), we need to use *_x_*
394|    // because **x** is STRONG(x):
395|    if (node->parent && node->parent->type == CMARK_NODE_EMPH &&
396|        node->next == NULL && node->prev == NULL) {
397|      emph_delim = "_";
398|    } else {
399|      emph_delim = "*";
400|    }
401|    if (entering) {
402|      LIT(emph_delim);
403|    } else {
404|      LIT(emph_delim);
405|    }
406|    break;
407|
408|  case CMARK_NODE_LINK:
409|    if (is_autolink(node)) {
410|      if (entering) {
411|        LIT("<");
412|        if (strncmp(cmark_node_get_url(node), "mailto:", 7) == 0) {
413|          LIT((const char *)cmark_node_get_url(node) + 7);
414|        } else {
415|          LIT((const char *)cmark_node_get_url(node));
416|        }
417|        LIT(">");
418|        // return signal to skip contents of node...
419|        return 0;
420|      }
421|    } else {
422|      if (entering) {
423|        LIT("[");
424|      } else {
425|        LIT("](");
426|        OUT(cmark_node_get_url(node), false, URL);
427|        title = cmark_node_get_title(node);
428|        if (strlen(title) > 0) {
429|          LIT(" \"");
430|          OUT(title, false, TITLE);
431|          LIT("\"");
432|        }
433|        LIT(")");
434|      }
435|    }
436|    break;
437|
438|  case CMARK_NODE_IMAGE:
439|    if (entering) {
440|      LIT("![");
441|    } else {
442|      LIT("](");
443|      OUT(cmark_node_get_url(node), false, URL);
444|      title = cmark_node_get_title(node);
445|      if (strlen(title) > 0) {
446|        OUT(" \"", allow_wrap, LITERAL);
447|        OUT(title, false, TITLE);
448|        LIT("\"");
449|      }
450|      LIT(")");
451|    }
452|    break;
453|
454|  default:
455|    assert(false);
456|    break;
457|  }
458|
459|  return 1;
460|}

20|static inline void outc(cmark_renderer *renderer, cmark_escaping escape,
21|                        int32_t c, unsigned char nextc) {
22|  if (escape == LITERAL) {
23|    cmark_render_code_point(renderer, c);
24|    return;
25|  }
26|
27|  switch (c) {
28|  case 123: // '{'
29|  case 125: // '}'
30|  case 35:  // '#'
31|  case 37:  // '%'
32|  case 38:  // '&'
33|    cmark_render_ascii(renderer, "\\");
34|    cmark_render_code_point(renderer, c);
35|    break;
36|  case 36: // '$'
37|  case 95: // '_'
38|    if (escape == NORMAL) {
39|      cmark_render_ascii(renderer, "\\");
40|    }
41|    cmark_render_code_point(renderer, c);
42|    break;
43|  case 45:             // '-'
44|    if (nextc == 45) { // prevent ligature
45|      cmark_render_ascii(renderer, "-{}");
46|    } else {
47|      cmark_render_ascii(renderer, "-");
48|    }
49|    break;
50|  case 126: // '~'
51|    if (escape == NORMAL) {
52|      cmark_render_ascii(renderer, "\\textasciitilde{}");
53|    } else {
54|      cmark_render_code_point(renderer, c);
55|    }
56|    break;
57|  case 94: // '^'
58|    cmark_render_ascii(renderer, "\\^{}");
59|    break;
60|  case 92: // '\\'
61|    if (escape == URL) {
62|      // / acts as path sep even on windows:
63|      cmark_render_ascii(renderer, "/");
64|    } else {
65|      cmark_render_ascii(renderer, "\\textbackslash{}");
66|    }
67|    break;
68|  case 124: // '|'
69|    cmark_render_ascii(renderer, "\\textbar{}");
70|    break;
71|  case 60: // '<'
72|    cmark_render_ascii(renderer, "\\textless{}");
73|    break;
74|  case 62: // '>'
75|    cmark_render_ascii(renderer, "\\textgreater{}");
76|    break;
77|  case 91: // '['
78|  case 93: // ']'
79|    cmark_render_ascii(renderer, "{");
80|    cmark_render_code_point(renderer, c);
81|    cmark_render_ascii(renderer, "}");
82|    break;
83|  case 34: // '"'
84|    cmark_render_ascii(renderer, "\\textquotedbl{}");
85|    // requires \usepackage[T1]{fontenc}
86|    break;
87|  case 39: // '\''
88|    cmark_render_ascii(renderer, "\\textquotesingle{}");
89|    // requires \usepackage{textcomp}
90|    break;
91|  case 160: // nbsp
92|    cmark_render_ascii(renderer, "~");
93|    break;
94|  case 8230: // hellip
95|    cmark_render_ascii(renderer, "\\ldots{}");
96|    break;
97|  case 8216: // lsquo
98|    if (escape == NORMAL) {
99|      cmark_render_ascii(renderer, "`");
100|    } else {
101|      cmark_render_code_point(renderer, c);
102|    }
103|    break;
104|  case 8217: // rsquo
105|    if (escape == NORMAL) {
106|      cmark_render_ascii(renderer, "\'");
107|    } else {
108|      cmark_render_code_point(renderer, c);
109|    }
110|    break;
111|  case 8220: // ldquo
112|    if (escape == NORMAL) {
113|      cmark_render_ascii(renderer, "``");
114|    } else {
115|      cmark_render_code_point(renderer, c);
116|    }
117|    break;
118|  case 8221: // rdquo
119|    if (escape == NORMAL) {
120|      cmark_render_ascii(renderer, "''");
121|    } else {
122|      cmark_render_code_point(renderer, c);
123|    }
124|    break;
125|  case 8212: // emdash
126|    if (escape == NORMAL) {
127|      cmark_render_ascii(renderer, "---");
128|    } else {
129|      cmark_render_code_point(renderer, c);
130|    }
131|    break;
132|  case 8211: // endash
133|    if (escape == NORMAL) {
134|      cmark_render_ascii(renderer, "--");
135|    } else {
136|      cmark_render_code_point(renderer, c);
137|    }
138|    break;
139|  default:
140|    cmark_render_code_point(renderer, c);
141|  }
142|}

